function tacticsView(g,t){
 const identity=tacticIdentity(t),era=window.FLLegacySystems?FLLegacySystems.tacticalContext(g,t.tactics,t.positions):null,execution=era?Math.round(era.execution*100):100;
 const controls=[
  ['mentality','Mentality','Controls risk, numbers committed forward and how urgently the side attacks.'],
  ['tempo','Tempo','How quickly players move the ball and attempt to progress attacks.'],
  ['passing','Passing Directness','From short combinations to early forward passes and long balls.'],
  ['width','Attacking Width','How much the team stretches the pitch while in possession.'],
  ['defensiveLine','Defensive Line','How high the back line holds its position without the ball.'],
  ['pressing','Pressing Intensity','How aggressively players close opponents and contest possession.'],
  ['creativeFreedom','Creative Freedom','How strictly players follow structure or improvise.'],
  ['timeWasting','Game Management','How willing the team is to slow play and protect the match state.'],
  ['buildUp','Transition Speed','From patient construction to immediate counter-attacks.']
 ];
 return `<div class="tactics-page">
  <section class="philosophy-banner"><div><span>CURRENT PLAYING STYLE</span><h2 id="playingStyle">${identity.style}</h2></div><div><span>TEAM PHILOSOPHY</span><h2 id="teamPhilosophy">${identity.philosophy}</h2></div><p>Your identity is generated from the instructions below. It will influence how the match engine interprets possession, chance creation, pressing and defensive shape.</p></section>
  <div class="tactics-layout"><section class="panel tactics-controls"><div class="panel-head">TEAM INSTRUCTIONS <span>Changes save automatically</span></div><div class="slider-list">${controls.map(([key,label,help])=>`<div class="tactic-slider"><div class="slider-copy"><label for="tactic-${key}">${label}</label><p>${help}</p></div><div class="slider-control"><strong data-tactic-label="${key}">${sliderLabel(key,t.tactics[key])}</strong><input id="tactic-${key}" type="range" min="0" max="100" step="1" value="${t.tactics[key]}" data-tactic="${key}"><div class="range-ends"><span>${sliderLabel(key,0)}</span><span>${sliderLabel(key,100)}</span></div></div></div>`).join('')}</div></section>
  <aside class="panel tactical-effects"><div class="panel-head">MATCH ENGINE EFFECTS</div><div class="effect-list">
   <div><span>Possession intent</span><strong id="effectPossession">${Math.round((100-t.tactics.passing+t.tactics.buildUp)/2)}%</strong></div>
   <div><span>Attacking risk</span><strong id="effectRisk">${Math.round((t.tactics.mentality+t.tactics.tempo)/2)}%</strong></div>
   <div><span>Pressing load</span><strong id="effectPress">${Math.round((t.tactics.pressing+t.tactics.defensiveLine)/2)}%</strong></div>
   <div><span>Defensive security</span><strong id="effectSecurity">${Math.round((100-t.tactics.mentality+100-t.tactics.defensiveLine)/2)}%</strong></div>
   <div><span>Player freedom</span><strong id="effectFreedom">${t.tactics.creativeFreedom}%</strong></div>
  </div><div class="tactics-note"><strong>Free tactical board.</strong><p>Drag players into any shape. The era never blocks your idea; it changes how quickly contemporary players understand and execute it.</p></div>${era?`<section class="era-tactics-card"><div class="era-tactics-head"><span>${era.eraLabel}</span><strong>${execution}% execution</strong></div><div class="execution-meter"><i style="width:${Math.min(100,execution)}%"></i></div><div class="era-tactics-stats"><div><span>System familiarity</span><b>${Math.round(era.familiarity)}%</b></div><div><span>Innovation reputation</span><b>${Math.round(era.innovation)}%</b></div><div><span>Positioning</span><b>Completely free</b></div></div><p>${era.warnings.join(' ')}</p><small>Contemporary language: ${era.availableLanguage.join(' · ')}</small></section>`:''}</aside></div>
 </div>`;
}

