 if(p.position==='FB')return {...common,Tackling:bump(4),Marking:bump(3),Crossing:bump(0),Passing:bump(-1),Heading:bump(1),Positioning:bump(3)};
 if(p.position==='HB')return {...common,Tackling:bump(3),Passing:bump(2),Vision:bump(1),Positioning:bump(3),Heading:bump(1),'Long Shots':bump(-1)};
 if(p.position==='W')return {...common,Dribbling:bump(4),Crossing:bump(4),Acceleration:bump(3),Finishing:bump(0),'First Touch':bump(2),Movement:bump(2)};
 if(p.position==='CF')return {...common,Finishing:bump(5),Heading:bump(3),Movement:bump(4),'First Touch':bump(2),Passing:bump(-2),'Long Shots':bump(1)};
