function ensurePlayerCareers(g){
 const c=controlled(g),places=['Accrington','Blackburn','Bolton','Burnley','Liverpool','Manchester','Preston','Sheffield','Stoke','Wolverhampton'],feet=['Right','Right','Right','Left'],builds=['Slight','Lean','Average','Athletic','Broad','Powerful'],curves=['early','steady','steady','late','volatile'];
 c.players.forEach((p,i)=>{if(window.FLLivingWorld)FLLivingWorld.ensurePlayer(g,p,c);const n=i+1,seed=(p.id.length*13+n*17+p.age)%97,rv=k=>25+((seed*(k+7)+i*11)%74);
  p.number=p.number||n;p.nationality=p.nationality||'English';p.birthplace=p.birthplace||places[seed%places.length];p.preferredFoot=p.preferredFoot||feet[seed%feet.length];p.height=p.height||`${5+(seed%2)}' ${6+(seed%7)}"`;p.weight=p.weight||`${9+(seed%5)} st ${seed%14} lb`;p.bodyType=p.bodyType||builds[seed%builds.length];if(window.FLEraIdentity)FLEraIdentity.applyPlayer(g,p);else p.face=p.face||NO_PLAYER_FACE;
  p.ability=p.ability||55;p.ceiling=p.ceiling||Math.min(98,p.ability+8+(seed%18));p.potential=p.potential||Math.round(p.ability+(p.ceiling-p.ability)*.72);p.developmentCurve=p.developmentCurve||curves[seed%curves.length];
  p.personalityProfile=p.personalityProfile||{professionalism:rv(1),ambition:rv(2),loyalty:rv(3),leadership:rv(4),bigMatches:rv(5),consistency:rv(6),injuryProneness:rv(7),temperament:rv(8),teamwork:rv(9),determination:rv(10),adaptability:rv(11)};p.personalityLabel=p.personalityLabel||['Professional','Driven','Balanced','Loyal','Ambitious','Temperamental'][seed%6];
  p.morale=p.morale||['Excellent','Good','Good','Fair'][seed%4];p.squadStatus=p.squadStatus||(i<11?'First Team':i<16?'Rotation':'Backup');p.contractStart=p.contractStart||'1888-07-01';p.contractEnd=p.contractEnd||`${1889+(seed%4)}-06-30`;p.contractType=p.contractType||'Part-time';p.contractStatus=p.contractStatus||((Number(p.contractEnd.slice(0,4))-1888)<=1?'Expiring':'Secure');
  ['starts','subApps','minutes','assists','yellowCards','redCards','cleanSheets','conceded','playerOfMatch'].forEach(k=>p[k]=p[k]||0);p.averageRating=p.averageRating||'—';p.injuries=p.injuries||[];p.suspension=p.suspension||null;p.careerTotals=p.careerTotals||{appearances:p.appearances||0,goals:p.goals||0,assists:p.assists||0,cleanSheets:p.cleanSheets||0};p.clubHistory=p.clubHistory||[{club:c.name,from:Math.max(1884,1888-Math.max(0,p.age-18)),to:'Present',apps:p.careerTotals.appearances,goals:p.careerTotals.goals}];p.positions=p.positions||[p.position];p.seasonHistory=p.seasonHistory||[];p.matchHistory=p.matchHistory||[];normalisePlayerHonours(p);
 });if(!g.squadState)g.squadState={view:'overview',selectedPlayerId:null,profileView:'overview',sort:'rating',position:'ALL'};if(['appearances','goals','discipline'].includes(g.squadState.view))g.squadState.view='stats';if(!['overview','stats','contracts'].includes(g.squadState.view))g.squadState.view='overview';if(g.squadState.profileView==='career')g.squadState.profileView='history';if(!['overview','attributes','relationship','records','history','honours','negotiations'].includes(g.squadState.profileView))g.squadState.profileView='overview';if(!g.squadState.sort)g.squadState.sort='rating';if(!g.squadState.position)g.squadState.position='ALL';if(!['team','individual'].includes(g.squadState.honoursTab))g.squadState.honoursTab='team';return g.squadState;
}
function contractLabel(p){if(p?.partTime||p?.contractType==='Amateur registration')return 'AMATEUR';const year=Number((p.contractEnd||'1889').slice(0,4));return year<=1889?'EXPIRING':year===1890?'18 MONTHS':`${year-1888} YEARS`;}
function profileTabs(state,includeNegotiations=false,includeRelationship=true){const tabs=[['overview','OVERVIEW'],['attributes','PLAYER RATINGS'],...(includeRelationship?[['relationship','RELATIONSHIP']]:[]),['records','RECORDS'],['history','TIMELINE'],['honours','HONOURS & AWARDS']];if(includeNegotiations)tabs.push(['negotiations','APPROACH TO SIGN']);return `<div class="section-tabs profile-tabs">${tabs.map(([k,l])=>`<button class="${state.profileView===k?'active':''}" data-profile-view="${k}">${l}</button>`).join('')}</div>`;}
