 if(g._worldDecoratedStamp!==stamp){g.clubs.forEach(c=>(c.players||[]).forEach((p,i)=>decorate(p,i,c)));g.freeAgents.forEach((p,i)=>decorate(p,i,null));foreignClubs.forEach(c=>(c.players||[]).forEach((p,i)=>decorate(p,i,c)));(g.globalPlayers||[]).filter(p=>p.status==='global-prospect').forEach((p,i)=>decorate(p,i,null));g._worldDecoratedStamp=stamp;}
 if(!g.worldUI)g.worldUI={clubId:null,playerId:null,query:'',position:'ALL',minRating:'ANY',maxAge:'ANY',source:'all',searchSubmitted:false,shortlist:[],negotiations:[],pyramidDivisionId:null,competitionMode:'english',worldLeagueId:null};
