function money(n){return `£${Math.round(Number(n)||0).toLocaleString('en-GB')}`;}

function clubPlayerCareerRows(g,c){
 return historyPlayerEntries(g).map(({p})=>{
  const seasons=historyArray(p.seasonHistory).filter(row=>row.clubId===c.id||row.club===c.name),current=Number(p.clubId===c.id||c.players?.some(x=>x.id===p.id));
  let apps=seasons.reduce((n,row)=>n+historyNumber(row.apps??row.appearances),0),goals=seasons.reduce((n,row)=>n+historyNumber(row.goals),0),assists=seasons.reduce((n,row)=>n+historyNumber(row.assists),0),cleanSheets=seasons.reduce((n,row)=>n+historyNumber(row.cleanSheets),0);
  const currentSeason=seasons.some(row=>row.season===currentSeasonLabel(g));
  if(current&&!currentSeason){apps+=historyNumber(p.appearances);goals+=historyNumber(p.goals);assists+=historyNumber(p.assists);cleanSheets+=historyNumber(p.cleanSheets);}
  if(!seasons.length&&current){apps=Math.max(apps,historyNumber(p.appearances));goals=Math.max(goals,historyNumber(p.goals));assists=Math.max(assists,historyNumber(p.assists));cleanSheets=Math.max(cleanSheets,historyNumber(p.cleanSheets));}
  return {p,apps,goals,assists,cleanSheets};
 }).filter(row=>row.apps||row.goals||row.assists||row.cleanSheets||c.players?.some(x=>x.id===row.p.id));
}
