function records(g){return `<section class="page">${title('HISTORY','A permanent record of your football world.')}<div class="message-list">${g.history.length?g.history.map(h=>`<div class="news-row" style="padding:16px"><strong>${h.text}</strong><span>${formatDate(h.date)}</span></div>`).join(''):'<div class="panel-body">History begins when the first competitive matches are played.</div>'}</div></section>`;}

function simpleComingSoon(g,heading,copy){return `<section class="page">${title(heading,copy)}<section class="panel"><div class="panel-head">${heading.toUpperCase()}</div><div class="panel-body"><p>This section is ready to be built next. The existing game systems have been left unchanged.</p></div></section></section>`;}
function installListScrollPassThrough(){
 if(document.body.classList.contains('match-mode')||document.body.classList.contains('lineup-mode'))return;
 const main=document.getElementById('mainPanel');if(!main||main.dataset.pageWheelFixed==='1')return;main.dataset.pageWheelFixed='1';
 const selector='.table-wrap,.history-ranking,.history-club-directory,.history-player-directory,.history-manager-directory,.history-transfer-list,.world-list,.global-search-results,.competition-leader-list,.club-career-list,.history-record-list,.match-records';
 main.addEventListener('wheel',event=>{if(document.body.classList.contains('match-mode')||document.body.classList.contains('lineup-mode')||Math.abs(event.deltaY)<=Math.abs(event.deltaX)||!event.target.closest(selector))return;const pageScroller=document.scrollingElement||document.documentElement,before=pageScroller.scrollTop;pageScroller.scrollTop+=event.deltaY;if(pageScroller.scrollTop!==before)event.preventDefault();},{passive:false,capture:true});
}
