function boardConversationsView(g){const topics=window.FLLivingWorld?FLLivingWorld.availableBoardTopics(g):[],history=g.livingWorld?.boardTalks||[];return `<div class="living-two-column"><section class="panel"><div class="panel-head">TALK TO THE BOARD <span>Choose an approach, not a generic mood</span></div><div class="conversation-topic-list">${topics.map(t=>`<article class="conversation-topic ${t.locked?'locked':''}"><div><span>${t.minTrust||0}% TRUST</span><h3>${t.title}</h3><p>${t.detail}</p>${t.locked?`<small>${t.lockReason}</small>`:''}</div><div class="conversation-options">${t.options.map(o=>`<button data-board-talk="${t.id}" data-board-talk-option="${o.id}" ${t.locked?'disabled':''}><strong>${o.label}</strong><span>${o.tone}</span></button>`).join('')}</div></article>`).join('')}</div></section><section class="panel"><div class="panel-head">RECENT BOARD RESPONSES</div><div class="club-timeline">${history.slice().reverse().slice(0,12).map(x=>`<article><time>${formatDate(x.date)}</time><div><strong>${x.title}</strong><p>You chose “${x.choice}”. ${x.reply}</p></div></article>`).join('')||'<p class="empty-note">No extended discussion has taken place yet.</p>'}</div></section></div>`;}
function clubFutureView(g){const f=window.FLLivingWorld?FLLivingWorld.clubFuture(g):{identity:{},heritage:{traditions:[]},staff:[],pending:[],warReturns:[],richBids:[],trust:50,influence:'Advisory voice'},d=[...f.warReturns,...f.richBids,...f.pending],i=f.identity||{},c=controlled(g),authority=f.trust>=75,design=i.design||{primary:c.primary||'#7b1d2a',secondary:c.secondary||'#eeeade',kitPattern:c.kitPattern||'plain',badgeShape:c.badgeShape||'shield'};return `<div class="living-two-column"><section class="panel"><div class="panel-head">CLUB IDENTITY & COMMERCIAL FUTURE</div><div class="identity-summary"><div><span>Official identity</span><strong>${i.officialName||c.name}</strong></div><div><span>Kit direction</span><strong>${i.kitEra||'Traditional'}</strong></div><div><span>Badge era</span><strong>${i.badgeEra||'Founding crest'}</strong></div><div><span>Current sponsor</span><strong>${i.sponsors?.at(-1)?.name||'None'}</strong></div><div><span>Kit manufacturer</span><strong>${i.manufacturer?.name||'Club-made / local supply'}</strong></div><div><span>Your board influence</span><strong>${f.trust}% · ${f.influence}</strong></div></div><p class="board-influence-note">Below 60% trust, your identity choices are recommendations. At 60–74% they are usually followed. At 75% and above, the board gives you final authority.</p>${livingDecisionCards(g,d,'No kit, badge, sponsor, manufacturer, name or overseas-transfer decision is waiting.')}</section><section class="panel club-design-panel ${authority?'unlocked':'locked'}"><div class="panel-head">KIT & BADGE DESIGN AUTHORITY <span>${authority?'UNLOCKED':`${Math.max(0,75-f.trust)}% MORE TRUST NEEDED`}</span></div><div class="club-design-preview" style="--design-a:${design.primary};--design-b:${design.secondary}"><div class="design-shirt pattern-${design.kitPattern}"><i></i></div><div class="design-badge shape-${design.badgeShape}">${c.initials}</div></div><div class="club-design-controls"><label>Primary colour<input id="clubDesignPrimary" type="color" value="${design.primary}" ${authority?'':'disabled'}></label><label>Secondary colour<input id="clubDesignSecondary" type="color" value="${design.secondary}" ${authority?'':'disabled'}></label><label>Kit pattern<select id="clubDesignPattern" ${authority?'':'disabled'}><option value="plain" ${design.kitPattern==='plain'?'selected':''}>Plain</option><option value="stripes" ${design.kitPattern==='stripes'?'selected':''}>Stripes</option><option value="halves" ${design.kitPattern==='halves'?'selected':''}>Halves</option><option value="hoops" ${design.kitPattern==='hoops'?'selected':''}>Hoops</option><option value="sash" ${design.kitPattern==='sash'?'selected':''}>Sash</option></select></label><label>Badge shape<select id="clubDesignBadge" ${authority?'':'disabled'}><option value="shield" ${design.badgeShape==='shield'?'selected':''}>Shield</option><option value="round" ${design.badgeShape==='round'?'selected':''}>Round</option><option value="diamond" ${design.badgeShape==='diamond'?'selected':''}>Diamond</option></select></label></div><button class="wide-action" data-save-club-design ${authority?'':'disabled'}>${authority?'SAVE KIT & BADGE':'BOARD AUTHORITY LOCKED'}</button><p class="club-design-note">Every saved design is dated and retained in the club’s kit and badge history for future match presentation.</p></section><section class="panel"><div class="panel-head">FORMER PLAYERS IN CLUB ROLES <span>${f.staff.length}</span></div><div class="staff-list">${f.staff.map(x=>`<article><div class="director-monogram">${x.name.split(' ').map(n=>n[0]).join('')}</div><span><strong>${x.name}</strong><small>${x.role}${x.formerPlayer?' · former player':''}</small></span><time>${formatDate(x.appointed)}</time></article>`).join('')||'<p class="empty-note">No former player has yet moved into a permanent club role.</p>'}</div><div class="panel-head">DEVELOPING TRADITIONS</div><div class="heritage-tags">${(f.heritage?.traditions||[]).map(x=>`<b>${x}</b>`).join('')||'<span class="empty-note">Traditions will emerge from results, youth development, loyalty and famous matches.</span>'}</div></section></div>`;}
function governanceView(g){const pending=window.FLLivingWorld?FLLivingWorld.pending(g,'governance'):[],history=g.livingWorld?.governanceHistory||[];return `<div class="living-two-column"><section class="panel"><div class="panel-head">FOOTBALL GOVERNANCE VOTES</div>${livingDecisionCards(g,pending,'There is no league or association vote open today.')}</section><section class="panel"><div class="panel-head">YOUR VOTING RECORD</div><div class="club-timeline">${history.slice().reverse().map(x=>`<article><time>${formatDate(x.date)}</time><div><strong>${x.title}</strong><p>You chose “${x.choice}”. Final outcome: ${x.officialOutcome}. Influence: ${x.influence}.</p></div></article>`).join('')||'<p class="empty-note">Your first formal football vote has not yet arrived.</p>'}</div></section></div>`;}
