 if(!rows.length)return `<div class="memorial-page"><section class="panel memorial-quiet"><div class="panel-head">WARTIME REMEMBRANCE</div><div class="empty-profile-state club-empty"><strong>No wartime losses recorded for ${c.name}</strong></div></section></div>`;
