 const replyButtons=active?.open?(active.group==='players'?active.choices.map(ch=>`<button data-conversation-reply="${ch.id}" data-player-id="${active.roleId}"><strong>${ch.label}</strong><small>${ch.tone}</small></button>`).join(''):active.choices.map(ch=>`<button data-generic-reply="${ch.id}" data-thread-id="${active.id}"><strong>${ch.label}</strong><small>${ch.tone}</small></button>`).join('')):'';
