function boardIndexedAmount(g,base,kind='budget'){
 const year=Number(String(g?.date||'1888').slice(0,4))||1888;
 if(!window.FLEconomy)return Math.max(0,Math.round(base));
 const current=kind==='wage'?FLEconomy.wageIndex(year):FLEconomy.budgetIndex(year),origin=kind==='wage'?FLEconomy.wageIndex(1888):FLEconomy.budgetIndex(1888);
 const raw=Math.max(0,Number(base||0)*(current/Math.max(.0001,origin)));
 const step=raw>=10000000?1000000:raw>=1000000?100000:raw>=100000?10000:raw>=10000?1000:raw>=1000?100:raw>=100?10:1;
 return Math.max(base?1:0,Math.round(raw/step)*step);
}
function refreshBoardEconomy(g,b){
 const wageTarget=boardIndexedAmount(g,8,'wage'),costs={training:350,transfer:250,stadium:100};
 const wageRequest=(b.requests||[]).find(x=>x.id==='wages');if(wageRequest){wageRequest.baseWeeklySaving=8;wageRequest.weeklySaving=wageTarget;wageRequest.detail=`Lower weekly player wages by ${money(wageTarget)} before the season ends.`;}
 for(const proposal of b.proposals||[]){if(!(proposal.id in costs))continue;proposal.baseCost=costs[proposal.id];proposal.cost=boardIndexedAmount(g,costs[proposal.id],'budget');if(proposal.id==='transfer')proposal.detail=`Request an additional ${money(proposal.cost)} for recruitment.`;}
 b.economyYear=Number(String(g?.date||'1888').slice(0,4))||1888;
 return b;
}
