utton><button data-manager-contract="reject" class="danger">REJECT</button></div></article>`:'<div class="empty-profile-state">No new contract offer is currently awaiting a decision.</div>'}</section><section class="panel contract-history"><div class="panel-head">TERMS HISTORY</div><div class="meeting-log">${(contract.wageHistory||[]).slice(0,8).map(x=>`<article><time>${formatDate(x.date)}</time><p><strong>${money(x.weeklyWage)} per week</strong> · ${x.reason}</p></article>`).join('')}</div>${history.length?`<div class="panel-head secondary">OFFER HISTORY</div><div class="meeting-log">${history.map(x=>`<article><time>${formatDate(x.decisionDate||x.offeredDate)}</time><p>${x.status} · ${x.lengthYears} years at ${money(x.weeklyWage)} per week</p></article>`).join('')}</div>`:''}</section></div>`;
