 const legacyRecord=window.FLManagerLegacyCareer&&FLManagerLegacyCareer._test?.updateRecords?FLManagerLegacyCareer._test.updateRecords(g):null,archivedPlayed=Number(legacyRecord?.played)||0,archivedWins=Number(legacyRecord?.won)||0,archivedDraws=Number(legacyRecord?.drawn)||0,archivedLosses=Number(legacyRecord?.lost)||0,archivedGf=Number(legacyRecord?.gf)||0,archivedGa=Number(legacyRecord?.ga)||0,totalPlayed=archivedPlayed+played.length,totalWins=archivedWins+wins,totalDraws=archivedDraws+draws,totalLosses=archivedLosses+losses,totalGf=archivedGf+gf,totalGa=archivedGa+ga,totalWinPct=totalPlayed?Math.round(totalWins/totalPlayed*100):0,displayLongest=played.length?longest:(archivedPlayed?'—':0),table=FLGame.table(g),position=table.findIndex(x=>x.id===c.id)+1;
