function ensureSettings(g){
 if(!g.settings)g.settings={};
 const s=g.settings;
 if(!s.view)s.view='general';
 if(!s.simulationSpeed)s.simulationSpeed='normal';
 if(!Number.isFinite(Number(s.matchSpeed)))s.matchSpeed=1;
 if(!s.uiScale)s.uiScale='normal';
 if(typeof s.animations!=='boolean')s.animations=true;
 if(typeof s.reducedMotion!=='boolean')s.reducedMotion=false;
 if(typeof s.highContrast!=='boolean')s.highContrast=false;
 if(!s.textSize)s.textSize='normal';
 if(typeof s.confirmDestructive!=='boolean')s.confirmDestructive=true;
 return s;
}
function applySettings(g){
 const s=ensureSettings(g),root=document.documentElement,body=document.body;
 root.style.fontSize=s.textSize==='large'?'112.5%':s.textSize==='small'?'93.75%':'100%';
 body.classList.toggle('ui-compact',s.uiScale==='compact');
 body.classList.toggle('ui-large',s.uiScale==='large');
 body.classList.toggle('reduced-motion',s.reducedMotion||!s.animations);
 body.classList.toggle('high-contrast',s.highContrast);
}
function saveSize(g){try{return new Blob([JSON.stringify(g)]).size}catch{return 0}}
