  el.addEventListener('dragleave',()=>el.classList.remove('drop-target'));
  el.addEventListener('drop',e=>{e.preventDefault();e.stopPropagation();el.classList.remove('drop-target');const raw=e.dataTransfer.getData('text/plain'),target=Number(el.dataset.slot);if(raw.startsWith('player:'))swapBenchIntoSlot(raw.slice(7),target);else if(raw.startsWith('slot:')){const source=Number(raw.slice(5));if(source!==target){[t.startingXI[source],t.startingXI[target]]=[t.startingXI[target],t.startingXI[source]];t.selectedSlot=target}}save()});
