function ensureMatchUI(g){
 g.matchUI=g.matchUI||{recordId:null,minute:0,clockStep:0,playing:false,speed:1,shout:null,shoutUntilClock:0,substitutions:[],subsOpen:false,subOff:null,subOn:null,teamManagementOpen:false,teamManagementWasPlaying:false};
 if(!Number.isFinite(Number(g.matchUI.speed)))g.matchUI.speed=Math.max(1,Math.min(3,Number(g.settings?.matchSpeed)||1));
 if(!Array.isArray(g.matchUI.substitutions))g.matchUI.substitutions=[];
 if(g.matchUI.subsOpen==null)g.matchUI.subsOpen=false;
 if(g.matchUI.teamManagementOpen==null)g.matchUI.teamManagementOpen=false;
 if(g.matchUI.teamManagementWasPlaying==null)g.matchUI.teamManagementWasPlaying=false;
 g.matchUI.pitchPositions=g.matchUI.pitchPositions||{};
 g.matchUI.pitchVelocities=g.matchUI.pitchVelocities||{};
 if(g.matchUI.phase==null)g.matchUI.phase='pre-match';
 if(g.matchUI.halfTimeComplete==null)g.matchUI.halfTimeComplete=false;
 if(g.matchUI.goalEventKey==null)g.matchUI.goalEventKey=null;if(g.matchUI.dragSubOn==null)g.matchUI.dragSubOn=null;if(g.matchUI.lastSubstitutionMessage==null)g.matchUI.lastSubstitutionMessage='';
 if(!Number.isFinite(Number(g.matchUI.clockStep)))g.matchUI.clockStep=Math.round(Number(g.matchUI.minute||0)*4);
 if(!Number.isFinite(Number(g.matchUI.shoutUntilClock)))g.matchUI.shoutUntilClock=Number(g.matchUI.shoutUntil||0);
 return g.matchUI;
}
function matchClock(ui,record){const ticks=Number(record?.ticksPerMinute||4);return Number(ui.clockStep||0)/ticks;}
