function eventMinuteLabel(e){return Math.min(90,Math.max(1,Number(e?.minute||Math.floor(eventClockValue(e))+1)));}
function goalEventKey(e){return `${eventClockValue(e).toFixed(2)}-${e.side}-${e.playerId||e.player||''}`;}
function attackDirectionAt(side,clock){const first=clock<45;return side==='home'?(first?1:-1):(first?-1:1);}
function currentPitchState(record,minute){
 if(window.FLMatchEnvironment&&record?.conditions)return FLMatchEnvironment.surfaceAtMinute(record.conditions,minute);
 const wet=['Heavy rain','Light rain'].includes(record?.weather),start=record?.pitch||'Good';
 if(start==='Frozen')return minute>65?'Churned frozen':'Frozen';
 if(start==='Muddy'||wet){if(minute>=70)return 'Very muddy';if(minute>=35)return 'Muddy';return start==='Good'?'Soft':start;}
 if(start==='Soft'){if(minute>=65)return 'Muddy';if(minute>=30)return 'Worn';return 'Soft';}
 if(minute>=75)return 'Worn';if(minute>=40)return 'Slightly worn';return 'Good';
}
function matchEra(record,g){
 const year=Number(String(record?.date||g?.date||'1888').slice(0,4))||1888;
 return record?.presentationEra||(window.FLMatchEnvironment?FLMatchEnvironment.eraForYear(year):{id:year<1950?'interwar':year<1970?'postwar':year<1990?'television':year<2006?'modernising':'contemporary',label:'Football Era',broadcast:'Match Centre',kit:'Traditional football kit',ball:'Leather match ball',photo:'Press photograph'});
}
function matchFallbackFace(player,index=0){return player?.face||NO_PLAYER_FACE;}
