 const sideCard=side=>{const club=FLGame.club(g,side==='home'?record.homeId:record.awayId),line=activeLineup(record,side,ui),captain=[...line].filter(Boolean).sort((a,b)=>(b.ability||0)-(a.ability||0))[0]||line[8]||line[0]||{};return `<div class="era-player ${side}" style="--club-a:${club?.primary||'#8b2727'};--club-b:${club?.secondary||'#eeeade'}"><div class="era-player-photo">${playerPortrait(g,captain,'',captain.name||club?.name||side,club)}</div><div><small>${side==='home'?'HOME':'AWAY'} CAPTAIN</small><strong>${captain.name||'Club captain'}</strong><span>${club?.name||''} · ${era.kit}</span></div></div>`};
