 fixtures.forEach(f=>{const ours=f.home===c.id?historyNumber(f.homeGoals):historyNumber(f.awayGoals),theirs=f.home===c.id?historyNumber(f.awayGoals):historyNumber(f.homeGoals);gf+=ours;ga+=theirs;if(ours>theirs)won++;else if(ours===theirs)drawn++;else lost++;});
