 const filters=[['all','All events'],['competition','Competitions'],['rule','Rule changes'],['technology','Technology'],['war','Wars'],['club','Club foundations'],['legend','Legend prospects'],['society','Crowd & society'],['governance','Governance'],['season','Season milestones'],['manager','Manager history'],['result','Match results'],['transfer','Transfers']];
