function historyPage(g){
 let ui;
 try{
  ui=ensureHistoryUI(g);let body='';
  if(ui.view==='world')body=worldHistory(g);
  else if(ui.view==='seasons')body=ui.selectedSeason&&ui.seasonOpen?seasonPage(g,ui):seasonList(g,ui);
  else if(ui.view==='clubs')body=clubsHistory(g,ui);
  else if(ui.view==='players')body=playersHistory(g,ui);
  else if(ui.view==='managers')body=managersHistory(g,ui);
  else if(ui.view==='records')body=worldRecords(g,ui);
  else if(ui.view==='hall')body=worldHall(g);
  else if(ui.view==='awards')body=awardsArchive(g);
  else if(ui.view==='transfers')body=transfersArchive(g,ui);
  else if(ui.view==='timeline')body=milestones(g,ui);
  else body=historyDashboard(g,ui);
  return `<section class="page history-page">${title('HISTORY','Every season, player, club, manager and record preserved across the football world.')}${historyNav(ui)}${body}</section>`;
 }catch(error){
  console.error('Football Legacy history recovery',error);g.historyUI={view:'overview',selectedSeason:currentSeasonLabel(g),seasonView:'overview',seasonOpen:false,recordGroup:'players',record:'goals',recordLimit:50};
  return `<section class="page history-page">${title('HISTORY','The save remains playable while a damaged historical entry is isolated.')}<div class="history-recovery panel"><strong>HISTORY DATA RECOVERY</strong><p>A historical record could not be displayed. The History interface has been reset safely without deleting match, player or season data. Reopen the tab to continue.</p></div></section>`;
 }
}


function ensureGlobalSearch(g){g.globalSearch=g.globalSearch&&typeof g.globalSearch==='object'?g.globalSearch:{query:'',category:'all',submitted:false};if(!g.globalSearch.category)g.globalSearch.category='all';return g.globalSearch;}
